import sys
from collections import deque

def solve():
    input = sys.stdin.read().splitlines()
    ptr = 0
    t = int(input[ptr])
    ptr += 1
    for _ in range(t):
        while ptr < len(input) and input[ptr].strip() == '':
            ptr += 1
        n, k = map(int, input[ptr].split())
        ptr += 1
        adj = [[] for _ in range(n+1)]
        for __ in range(n-1):
            u, v = map(int, input[ptr].split())
            adj[u].append(v)
            adj[v].append(u)
            ptr += 1

        if n == 1:
            print(0 if k >= 1 else 1)
            continue
        if n == 2:
            print(0)
            continue

        leaves = 0
        degree = [0]*(n+1)
        for u in range(1, n+1):
            degree[u] = len(adj[u])
            if degree[u] == 1:
                leaves += 1

        if leaves == 0:
            print(0 if k >= 1 else n)
            continue

        max_operations = 0
        current_leaves = leaves
        current_nodes = n
        while current_nodes > 0:
            max_operations += 1
            if current_nodes == 1:
                break
            new_leaves = 0
            new_degree = degree.copy()
            for u in range(1, n+1):
                if degree[u] == 1:
                    for v in adj[u]:
                        new_degree[v] -= 1
                        if new_degree[v] == 1:
                            new_leaves += 1
            current_leaves = new_leaves
            current_nodes -= current_leaves
            degree = new_degree

        if k >= max_operations:
            print(0)
        else:
            print(max(0, n - k * leaves))

solve()
